INSERT INTO public.track_macro_programs (id, program_name, weeks) VALUES
('default-long-jump-speed-takeoff', 'Long Jump Runway Speed & Takeoff Power (4-Week Block)', '[{"title":"Week 1 - Takeoff Acceleration & Lift Foundation","drills":{"Saturday":[{"title":"Short-Approach Long Jump (6-8 Strides)","details":"Runway approach of 6-8 strides. Focus on penultimate drop and explosive takeoff.","type":"long_jump","percentage":95,"sets":"4","reps":"3","distance":null,"rest":"3m","unit":"contacts"},{"title":"Wickets Sprinting (Cones Run)","details":"Speed drill running over 10-15 mini hurdles/cones spaced to optimize vertical posture, front-side mechanics, and stride frequency.","type":"speed_max_velocity","percentage":100,"sets":"5","reps":"1","distance":"40","rest":"4m","unit":"meters"}],"Sunday":[],"Monday":[{"title":"Long Jump Takeoff from Box (15cm)","details":"Low box takeoff. Enhances vertical lift and flight posture (hang or hitch-kick).","type":"long_jump","percentage":90,"sets":"4","reps":"4","distance":null,"rest":"2m","unit":"contacts"},{"title":"Barbell Back Squat","details":"Full back squats to develop maximum leg strength and power.","type":"strength_double_leg","percentage":85,"sets":"4","reps":"5","distance":null,"rest":"3m","unit":"reps"}],"Tuesday":[],"Wednesday":[{"title":"Double-Leg Broad Jump to Sand Pit","details":"Horizontal explosive power from standing two-foot position.","type":"long_jump","percentage":90,"sets":"4","reps":"5","distance":null,"rest":"2m","unit":"contacts"},{"title":"Standing Cable Hip Flexion","details":"Ankle strap attached to low cable. Explode knee upward to hip height, then lower under control to build sprinting drive power.","type":"strength_single_leg","percentage":75,"sets":"3","reps":"8","distance":null,"rest":"75s","unit":"reps"}],"Thursday":[],"Friday":[]}},{"title":"Week 2 - Specific Power & Lift Optimization","drills":{"Saturday":[{"title":"Short-Approach Long Jump (6-8 Strides)","details":"Runway approach of 6-8 strides. Focus on penultimate drop and explosive takeoff.","type":"long_jump",