","unit":"meters"}],"Sunday":[],"Monday":[{"title":"Pop-Up Takeoff from 2-4 Strides","details":"Focus on rapid penultimate-to-ultimate contact. Jump high into the pit landing on the takeoff leg or butt.","type":"long_jump","percentage":85,"sets":"4","reps":"5","distance":null,"rest":"2m","unit":"contacts"},{"title":"Barbell Back Squat","details":"Full back squats to develop maximum leg strength and power.","type":"strength_double_leg","percentage":90,"sets":"3","reps":"3","distance":null,"rest":"3m","unit":"reps"}],"Tuesday":[],"Wednesday":[{"title":"Double-Leg Broad Jump to Sand Pit","details":"Horizontal explosive power from standing two-foot position.","type":"long_jump","percentage":90,"sets":"4","reps":"5","distance":null,"rest":"2m","unit":"contacts"},{"title":"Resisted Wall Drill Knee Drives","details":"Leaning against a wall at 45-degree angle. Loop band around feet and drive knees explosively in a piston motion.","type":"strength_single_leg","percentage":70,"sets":"4","reps":"10","distance":null,"rest":"75s","unit":"reps"}],"Thursday":[],"Friday":[]}},{"title":"Week 4 - Stride Taper & Technical Sharpness","drills":{"Saturday":[{"title":"Short-Approach Long Jump (6-8 Strides)","details":"Runway approach of 6-8 strides. Focus on penultimate drop and explosive takeoff.","type":"long_jump","percentage":90,"sets":"3","reps":"2","distance":null,"rest":"3m","unit":"contacts"},{"title":"3-Point Acceleration Sprints (30m)","details":"Sprint 30m from a 3-point track stance. Focus on piston-like drive and projection.","type":"speed_acceleration","percentage":95,"sets":"3","reps":"1","distance":"30","rest":"3m","unit":"meters"}],"Sunday":[],"Monday":[{"title":"Long Jump Takeoff from Box (15cm)","details":"Low box takeoff. Enhances vertical lift and flight posture (hang or hitch-kick).","type":"long_jump","percentage":85,"sets":"3","reps":"3","distance":null,"rest":"2m","unit":"contacts"},{"title":"Weighted Step-ups to Box (50cm)","details":"Step up onto box holding dumbbells. Focuses on explosive glute drive and knee tracking.","type":"strength_single_leg","percentage":70,"sets":"3","reps":"6","distance":null,"rest":"75s","unit":"reps"}],"Tuesday":[],"Wednesday":[{"title":"Hitch-Kick Technique on Springboard","details":"Use a low springboard or trampoline to gain air time. Practice cycling the legs (hitch-kick) in the air.","type":"long_jump","percentage":85,"sets":"3","reps":"4","distance":null,"rest":"3m","unit":"contacts"},{"title":"Lying Banded Psoas March","details":"Lying on back with resistance band around feet, pull one knee to chest while holding the other leg straight and stable. Highly specific hip flexor activation.","type":"strength_single_leg","percentage":60,"sets":"3","reps":"10","distance":null,"rest":"60s","unit":"reps"}],"Thursday":[],"Friday":[]}]'),

('default-triple-jump-stiffness-phases', 'Triple Jump Landing Stiffness & Phase Distribution (4-Week Block)', '[{"title":"Week 1 - Phase Coordination & Landing Stiffness","drills":{"Saturday":[{"title":"Triple Jump - Short Approach (6-8 Strides)","details":"Short runup focusing on landing phase coordination and Hop-Step-Jump rhythm.","type":"triple_jump","percentage":95,"sets":"4","reps":"3","distance":null,"rest":"4m","unit":"contacts"},{"title":"Alternate Leg Bounding to Pit (RLRL)","details":"Maximal horizontal projection bounds focusing on active clawing motion.","type":"triple_jump","percentage":90,"sets":"3","reps":"10","distance":null,"rest":"3m","unit":"contacts"}],"Sunday":[],"Monday":[{"title":"Depth Drop to Triple Jump Takeoff","details":"Step off a 30cm box, land, and immediately perform a triple jump Hop phase.","type":"triple_jump","percentage":95,"sets":"3","reps":"4","distance":null,"rest":"3m","unit":"contacts"},{"title":"Barbell Hip Thrust (Heavy)","details":"Maximum barbell hip thrust. Load glutes and hamstrings at short muscle lengths to build horizontal sprinting power.","type":"strength_double_leg","percentage":85,"sets":"4","reps":"6","distance":null,"rest":"2m","unit":"reps"}],"Tuesday":[],"Wednesday":[{"title":"Hop-to-Step Phase transition","details":"Focus on jumping from landing leg and driving opposite knee up for the Step phase.","type":"triple_jump","percentage":90,"sets":"4","reps":"4","distance":null,"rest":"3m","unit":"contacts"},{"title":"Ankle Pogo Hops","details":"Keep knees stiff, react solely through the ankle joint. (Ankle Stiffness)","type":"plyometrics","percentage":85,"sets":"3","reps":"15","rest":"1m","unit":"contacts"}],"Thursday":[],"Friday":[]}},{"title":"Week 2 - Unilateral Power & Shock Absorption","drills":{"Saturday":[{"title":"Triple Jump - Short Approach (6-8 Strides)","details":"Short runup focusing on landing phase coordination and Hop-Step-Jump rhythm.","type":"triple_jump","percentage":95,"sets":"4","reps":"4","distance":null,"rest":"4m","unit":"contacts"},{"title":"Continuous Step-Phase Bounding","details":"Perform consecutive step-phase bounds on the same leg. Promotes knee drive suspension and hip strength.","type":"triple_jump","percentage":90,"sets":"3","reps":"6","distance":null,"rest":"3m","unit":"contacts"}],"Sunday":[],"Monday":[{"title":"Single-Leg Speed Hops over Foam Obstacles","details":"Reactively hop on takeoff leg over 5 low hurdles into pit.","type":"triple_jump","percentage":85,"sets":"3","reps":"5","distance":null,"rest":"3m","unit":"contacts"},{"title":"Trap Bar Deadlift","details":"Deadlift using hex-bar to reduce spinal shear. Develops maximum posterior chain drive.","type":"strength_double_leg","percentage":85,"sets":"4","reps":"5","distance":null,"rest":"3m","unit":"reps"}],"Tuesday":[],"Wednesday":[{"title":"Step-to-Jump Phase transition","details":"Elevated step phase bounding into the sand pit. Develops hip strength.","type":"triple_jump","percentage":90,"sets":"4","reps":"4","distance":null,"rest":"3m","unit":"contacts"},{"title":"Single-Leg Hip Thrust (Weighted)","details":"Unilateral hip extension. Shoulders on bench, elevate one leg, drive hips upward against a dumbbell/plate for glute power.","type":"strength_single_leg","percentage":75,"sets":"3","reps":"8","distance":null,"rest":"90s","unit":"reps"}],"Thursday":[],"Friday":[]}},{"title":"Week 3 - Peak Velocity & Runway Integration","drills":{"Saturday":[{"title":"Full-Approach Triple Jump","details":"Full runway speed. Focus on even phase distribution (33% Hop, 30% Step, 37% Jump).","type":"triple_jump","percentage":100,"sets":"3","reps":"2","distance":null,"rest":"6m","unit":"contacts"},{"title":"Speed Bounds with Weighted Belt (2kg)","details":"Continuous alternative leg bounding on grass with a light weight belt. Focus on flat foot clawing action.","type":"triple_jump","percentage":90,"sets":"3","reps":"8","distance":null,"rest":"2.5m","unit":"contacts"}],"Sunday":[],"Monday":[{"title":"Depth Drop to Triple Jump Takeoff","details":"Step off a 30cm box, land, and immediately perform a triple jump Hop phase.","type":"triple_jump","percentage":95,"sets":"4","reps":"3","distance":null,"rest":"3m","unit":"contacts"},{"title":"Barbell Hip Thrust (Heavy)","details":"Maximum barbell hip thrust. Load glutes and hamstrings at short muscle lengths to build horizontal sprinting power.","type":"strength_double_leg","percentage":90,"sets":"3","reps":"4","distance":null,"rest":"2.5m","unit":"reps"}],"Tuesday":[],"Wednesday":[{"title":"Hop-to-Step Phase transition","details":"Focus on jumping from landing leg and driving opposite knee up for the Step phase.","type":"triple_jump","percentage":90,"sets":"4","reps":"4","distance":null,"rest":"3m","unit":"contacts"},{"title":"Standing Hop-Step-Jump into Pit","details":"Triple jump from a standing position. Focuses on producing horizontal power from zero velocity.","type":"triple_jump","percentage":85,"sets":"4","reps":"4","distance":null,"rest":"2m","unit":"contacts"}],"Thursday":[],"Friday":[]}},{"title":"Week 4 - Technical Taper & Stiffness Tuning","drills":{"Saturday":[{"title":"Triple Jump - Short Approach (6-8 Strides)","details":"Short runup focusing on landing phase coordination and Hop-Step-Jump rhythm.","type":"triple_jump","percentage":90,"sets":"3","reps":"2","distance":null,"rest":"4m","unit":"contacts"},{"title":"Continuous Hop Phase Bounds (RRR / LLL)","details":"Repetitive single-leg hops to develop specific landing stiffness.","type":"triple_jump","percentage":80,"sets":"3","reps":"4","distance":null,"rest":"3m","unit":"contacts"}],"Sunday":[],"Monday":[{"title":"Box-to-Box Step Phase (30cm boxes)","details":"Take off from a box, land on the same leg on the ground, then drive onto a second box. Teaches shock absorption.","type":"triple_jump","percentage":85,"sets":"3","reps":"3","distance":null,"rest":"3m","unit":"contacts"},{"title":"Single-Leg Romanian Deadlift (SL RDL)","details":"Dumbbell single-leg deadlift. Builds powerful hamstrings and glutes while enhancing balance.","type":"strength_single_leg","percentage":70,"sets":"3","reps":"6","distance":null,"rest":"90s","unit":"reps"}],"Tuesday":[],"Wednesday":[{"title":"Double-Arm Swing Coordination Bounds","details":"Bounding drills focusing exclusively on the double-arm punch technique at the takeoff of each phase.","type":"triple_jump","percentage":80,"sets":"4","reps":"4","distance":null,"rest":"2m","unit":"contacts"},{"title":"Ankle Pogo Hops","details":"Keep knees stiff, react solely through the ankle joint.","type":"plyometrics","percentage":80,"sets":"3","reps":"10","distance":null,"rest":"1m","unit":"contacts"}],"Thursday":[],"Friday":[]}}]')
